    private static readonly Dictionary<string, Geometry> Cache = new(StringComparer.OrdinalIgnoreCase);

    public static Geometry? Get(string? icon)
    {
        if (string.IsNullOrWhiteSpace(icon) || !Paths.TryGetValue(icon, out var path))
            return null;

        if (Cache.TryGetValue(icon, out var geometry))
            return geometry;

        geometry = StreamGeometry.Parse(path);
        Cache[icon] = geometry;
        return geometry;
    }
